  FillCircle(xx,yy,11);
end;

procedure TimerProc;
begin
  if (xx<>px) or (yy<>py) then
  begin
    var t := 1/10;
    var newx := round((1-t)*xx+t*px);
    var newy := round((1-t)*yy+t*py);
    (xx,yy) := (newx,newy);
  end;
end;

